#include <stdio.h>

int main(void) {
    int n, i, total = 0, v;
    scanf("%d", &n);
    for (i = 0; i < n; i++) {
        scanf("%d", &v);
        total += v;
    }
    printf("%d\n", total);
    return 0;
}

#include <stdio.h>

int main(void) {
    int n, i, v;
    int max;
    scanf("%d", &n);
    scanf("%d", &max);
    for (i = 1; i < n; i++) {
        scanf("%d", &v);
        if (v > max) {
            max = v;
        }
    }
    printf("%d\n", max);
    return 0;
}
